-- Seed pilot data for Bureau
-- Run with: sudo -u postgres psql -d bureau -f scripts/seed-pilot-data.sql

-- 1. Create pilot invite codes
INSERT INTO pilot_invites (code, expires_at)
VALUES 
  ('BUREAU_PILOT_001', '2027-12-31'::date),
  ('BUREAU_PILOT_002', '2027-12-31'::date),
  ('BUREAU_PILOT_003', '2027-12-31'::date)
ON CONFLICT (code) DO NOTHING;

-- 2. Create Travis's user (if not exists from auth flow)
-- This will be created by the auth flow, but we can prepare the workspace
-- User ID will be generated by auth.users during signup

-- Wait for Travis to sign up via auth flow first
-- Then run the rest of this script with his user_id

-- For now, just log what needs to be done after signup:
DO $$
BEGIN
  RAISE NOTICE 'Pilot invite codes created!';
  RAISE NOTICE 'Next steps:';
  RAISE NOTICE '1. Sign up at /auth/signup with BUREAU_PILOT_001';
  RAISE NOTICE '2. Get user_id from auth.users';
  RAISE NOTICE '3. Run seed-travis-workspace.sql with that user_id';
END $$;
